<script setup>import {initials} from '#shared/utils/format.js';definePageMeta({layout:'therapist'});const {user,logout}=useAuth();const {data:therapists}=await useFetch('/api/therapists');const therapist=computed(()=>therapists.value?.[0]);const {data:schedules}=await useFetch('/api/schedules',{default:()=>[]})</script><template><div><LayoutPageHeader title="Profil saya" description="Informasi akun dan jadwal kerja Anda." /><section class="panel form-panel"><span class="avatar large pastel">{{ initials(user?.name) }}</span><h2 class="mt-4">{{ user?.name }}</h2><p>{{ user?.email }}</p><p class="muted">{{ therapist?.employeeCode }} · {{ therapist?.locations.map(l=>l.name).join(', ') }}</p><UiButton class="mt-6" variant="secondary" @click="logout">Keluar dari akun</UiButton></section><section class="panel form-panel mt-5"><h2>Jadwal kerja</h2><div v-for="s in schedules.slice(0,22)" :key="s.id" class="billing-line"><span>{{ s.scheduleDate }}<small class="table-sub">{{ s.locationName }} · {{ s.startTime.slice(0,5) }}–{{ s.endTime.slice(0,5) }}</small></span><UiBadge :status="s.status" /></div></section></div></template>